/** Resolve definition-site vocabulary references to one assembly's live members. */
import { isActionRef, isQueryRef } from "../reactions/authoring/references.js";
import { applyWhereOps } from "./where-evaluation.js";
import { brandWhereOp } from "./where-ops.js";
/** Mutates only the fresh declaration passed to {@link resolveDeclaration}. */
export class AuthoredReferenceResolver {
    resolver;
    definitions;
    constructor(resolver, definitions) {
        this.resolver = resolver;
        this.definitions = definitions;
    }
    resolveDeclaration(name, declaration) {
        const site = `Reaction "${name}"`;
        for (const clause of declaration.when) {
            if (!("channel" in clause))
                this.resolveActionPattern(clause, site);
        }
        if (declaration.whereOps !== undefined) {
            declaration.whereOps = declaration.whereOps.map((op) => this.resolveWhereOp(op, site));
        }
        this.resolveThenNodes(declaration.then, site);
    }
    /** Vocabulary references must be the definitions installed in this assembly. */
    resolveComputation(ref, site) {
        const existing = this.definitions.computationNamed(ref.computationName);
        if (existing === ref)
            return ref;
        if (existing === undefined) {
            throw new Error(`${site}: computation "${ref.computationName}" is not in the assembled vocabulary.`);
        }
        throw new Error(`${site}: computation "${ref.computationName}" is not the definition installed by this assembly.`);
    }
    resolveActionPattern(pattern, site) {
        if (!isActionRef(pattern.action))
            return;
        const { refConcept, refAction } = pattern.action;
        const concept = this.resolver.concept(refConcept, site);
        const live = Reflect.get(concept, refAction);
        if (typeof live !== "function" || live.concept === undefined) {
            throw new Error(`${site}: "${refConcept}.${refAction}" is not an action of the instrumented concept.`);
        }
        pattern.action = live;
        pattern.concept = live.concept;
    }
    liveQuery(query, site) {
        if (!isQueryRef(query))
            return query;
        const { refConcept, refQuery } = query;
        const concept = this.resolver.concept(refConcept, site);
        const live = Reflect.get(concept, refQuery);
        if (typeof live !== "function" || live.queryName === undefined) {
            throw new Error(`${site}: "${refConcept}.${refQuery}" is not a query of the instrumented concept.`);
        }
        return live;
    }
    resolveWhereOp(op, site) {
        switch (op.op) {
            case "find":
            case "whether":
            case "no": {
                if (op.query === undefined)
                    return op;
                const query = this.liveQuery(op.query, site);
                return query === op.query ? op : brandWhereOp({ ...op, query });
            }
            case "compute":
                this.resolveComputation(op.computation, site);
                return op;
            case "holds":
                this.resolveComputation(op.fused.computation, site);
                return op;
            case "earlier":
                this.resolveActionPattern(op.pattern, site);
                return op;
            case "now":
            case "custom":
                return op;
        }
    }
    resolveThenNodes(nodes, site) {
        for (const node of nodes) {
            this.resolveActionPattern(node.action, site);
            if (node.transformOps === undefined)
                continue;
            const ops = node.transformOps.map((op) => this.resolveWhereOp(op, site));
            node.transformOps = ops;
            node.transform = (frames) => applyWhereOps(frames, ops, this.definitions.readEnv());
        }
    }
}
